package app.vera.coach.visionbeta;
import android.health.connect.*;
import android.health.connect.datatypes.*;
import android.health.connect.datatypes.units.*;
import android.os.OutcomeReceiver;
import org.json.*;
import java.time.*;
import java.util.*;
final class HealthWriter23 {
 static final String[] TYPES={"STEPS","EXERCISE","SLEEP","WEIGHT","NUTRITION","HYDRATION"};
 static String[] permissions(){ArrayList<String> p=new ArrayList<>();for(String t:TYPES){p.add("android.permission.health.READ_"+t);p.add("android.permission.health.WRITE_"+t);}p.add("android.permission.health.WRITE_DISTANCE");p.add("android.permission.health.READ_DISTANCE");p.add("android.permission.health.READ_ACTIVE_CALORIES_BURNED");return p.toArray(new String[0]);}
 static String status(Main a){JSONObject result=new JSONObject();JSONArray granted=new JSONArray(),missing=new JSONArray();for(String p:permissions()){if(android.os.Build.VERSION.SDK_INT>=34&&a.checkSelfPermission(p)==0)granted.put(p);else missing.put(p);}HealthReader.put(result,"supported",android.os.Build.VERSION.SDK_INT>=34);HealthReader.put(result,"granted",granted);HealthReader.put(result,"missing",missing);boolean core=true;for(String t:TYPES)for(String direction:new String[]{"READ_","WRITE_"})if(android.os.Build.VERSION.SDK_INT<34||a.checkSelfPermission("android.permission.health."+direction+t)!=0)core=false;HealthReader.put(result,"complete",core);JSONArray readable=new JSONArray(),writable=new JSONArray();String[] healthNames={"steps","workouts","sleep","weight","nutrition","hydration"};for(int i=0;i<TYPES.length;i++){if(android.os.Build.VERSION.SDK_INT>=34&&a.checkSelfPermission("android.permission.health.READ_"+TYPES[i])==0)readable.put(healthNames[i]);if(android.os.Build.VERSION.SDK_INT>=34&&a.checkSelfPermission("android.permission.health.WRITE_"+TYPES[i])==0)writable.put(healthNames[i]);}HealthReader.put(result,"readableTypes",readable);HealthReader.put(result,"writableTypes",writable);HealthReader.put(result,"readComplete",readable.length()==TYPES.length);HealthReader.put(result,"writeComplete",writable.length()==TYPES.length);HealthReader.put(result,"cardioMetricsComplete",android.os.Build.VERSION.SDK_INT>=34&&a.checkSelfPermission("android.permission.health.READ_DISTANCE")==0&&a.checkSelfPermission("android.permission.health.READ_ACTIVE_CALORIES_BURNED")==0);return result.toString();}
 static double number(JSONObject o,String k,double max)throws Exception{double n=o.getDouble(k);if(!Double.isFinite(n)||n<0||n>max)throw new Exception("Valor no válido");return n;}
 static Instant time(JSONObject o,String key)throws Exception{long n=o.getLong(key);if(n<946684800000L||n>System.currentTimeMillis()+60000)throw new Exception("Fecha no válida");return Instant.ofEpochMilli(n);}
 static void write(Main a,String ticket,String payload){
  if(ticket==null||!ticket.matches("[A-Za-z0-9_-]{1,100}"))return;
  try{JSONArray entries=new JSONArray(payload);if(entries.length()>100)throw new Exception("Lote demasiado grande");ArrayList<android.health.connect.datatypes.Record> list=new ArrayList<>();
   for(int i=0;i<entries.length();i++){JSONObject o=entries.getJSONObject(i);String id=o.getString("id"),owner=o.getString("owner"),type=o.getString("type");
    if(!id.matches("[A-Za-z0-9_-]{1,100}")||!owner.matches("[a-f0-9]{32}")||!o.optString("source").equals("vera")||!(Arrays.asList(TYPES).contains(type)||type.equals("DISTANCE"))||a.checkSelfPermission("android.permission.health.WRITE_"+type)!=0)throw new Exception("Registro o permiso no válido");
    long version=o.getLong("version");if(version<1)throw new Exception("Versión no válida");
    Metadata meta=new Metadata.Builder().setClientRecordId("vera23_"+owner+"_"+type+"_"+id).setClientRecordVersion(version).setRecordingMethod(o.optString("recordingMethod").equals("active")?Metadata.RECORDING_METHOD_ACTIVELY_RECORDED:Metadata.RECORDING_METHOD_MANUAL_ENTRY).build();
    Instant start=time(o,"start");if(type.equals("WEIGHT")){double kg=number(o,"value",1000);if(kg==0)throw new Exception("Peso no válido");list.add(new WeightRecord.Builder(meta,start,Mass.fromGrams(kg*1000)).build());continue;}
    Instant end=time(o,"end");if(!end.isAfter(start)||Duration.between(start,end).toHours()>48)throw new Exception("Intervalo no válido");
    switch(type){
     case "DISTANCE":list.add(new DistanceRecord.Builder(meta,start,end,Length.fromMeters(number(o,"value",1000000))).build());break;
     case "HYDRATION":list.add(new HydrationRecord.Builder(meta,start,end,Volume.fromLiters(number(o,"value",20000)/1000)).build());break;
     case "STEPS":double steps=number(o,"value",1000000);if(steps!=Math.floor(steps))throw new Exception("Pasos no válidos");list.add(new StepsRecord.Builder(meta,start,end,(long)steps).build());break;
     case "SLEEP":list.add(new SleepSessionRecord.Builder(meta,start,end).build());break;
     case "EXERCISE":int exercise=exerciseType24(o);list.add(new ExerciseSessionRecord.Builder(meta,start,end,exercise).setTitle(o.optString("title","Entrenamiento Vera")).build());break;
     case "NUTRITION":NutritionRecord.Builder n=new NutritionRecord.Builder(meta,start,end);if(o.has("value"))n.setEnergy(Energy.fromCalories(number(o,"value",90000)*1000));if(o.has("protein"))n.setProtein(Mass.fromGrams(number(o,"protein",10000)));if(o.has("carbs"))n.setTotalCarbohydrate(Mass.fromGrams(number(o,"carbs",10000)));if(o.has("fat"))n.setTotalFat(Mass.fromGrams(number(o,"fat",10000)));JSONObject micro=o.optJSONObject("nutrients");if(micro!=null){if(micro.has("fiber_g"))n.setDietaryFiber(Mass.fromGrams(number(micro,"fiber_g",10000)));if(micro.has("sugar_g"))n.setSugar(Mass.fromGrams(number(micro,"sugar_g",10000)));if(micro.has("sodium_mg"))n.setSodium(Mass.fromGrams(number(micro,"sodium_mg",1e7)/1000));if(micro.has("potassium_mg"))n.setPotassium(Mass.fromGrams(number(micro,"potassium_mg",1e7)/1000));if(micro.has("calcium_mg"))n.setCalcium(Mass.fromGrams(number(micro,"calcium_mg",1e7)/1000));if(micro.has("iron_mg"))n.setIron(Mass.fromGrams(number(micro,"iron_mg",1e7)/1000));if(micro.has("magnesium_mg"))n.setMagnesium(Mass.fromGrams(number(micro,"magnesium_mg",1e7)/1000));if(micro.has("vitaminC_mg"))n.setVitaminC(Mass.fromGrams(number(micro,"vitaminC_mg",1e7)/1000));if(micro.has("vitaminD_ug"))n.setVitaminD(Mass.fromGrams(number(micro,"vitaminD_ug",1e7)/1000000));if(micro.has("vitaminB12_ug"))n.setVitaminB12(Mass.fromGrams(number(micro,"vitaminB12_ug",1e7)/1000000));if(micro.has("vitaminA_ug"))n.setVitaminA(Mass.fromGrams(number(micro,"vitaminA_ug",1e7)/1000000));if(micro.has("vitaminE_mg"))n.setVitaminE(Mass.fromGrams(number(micro,"vitaminE_mg",1e7)/1000));if(micro.has("vitaminB1_mg"))n.setThiamin(Mass.fromGrams(number(micro,"vitaminB1_mg",1e7)/1000));if(micro.has("vitaminB2_mg"))n.setRiboflavin(Mass.fromGrams(number(micro,"vitaminB2_mg",1e7)/1000));if(micro.has("vitaminB3_mg"))n.setNiacin(Mass.fromGrams(number(micro,"vitaminB3_mg",1e7)/1000));if(micro.has("vitaminB5_mg"))n.setPantothenicAcid(Mass.fromGrams(number(micro,"vitaminB5_mg",1e7)/1000));if(micro.has("vitaminB6_mg"))n.setVitaminB6(Mass.fromGrams(number(micro,"vitaminB6_mg",1e7)/1000));if(micro.has("biotin_ug"))n.setBiotin(Mass.fromGrams(number(micro,"biotin_ug",1e7)/1000000));if(micro.has("folate_ug"))n.setFolate(Mass.fromGrams(number(micro,"folate_ug",1e7)/1000000));if(micro.has("zinc_mg"))n.setZinc(Mass.fromGrams(number(micro,"zinc_mg",1e7)/1000));if(micro.has("manganese_mg"))n.setManganese(Mass.fromGrams(number(micro,"manganese_mg",1e7)/1000));if(micro.has("copper_mg"))n.setCopper(Mass.fromGrams(number(micro,"copper_mg",1e7)/1000));if(micro.has("iodine_ug"))n.setIodine(Mass.fromGrams(number(micro,"iodine_ug",1e7)/1000000));if(micro.has("chromium_ug"))n.setChromium(Mass.fromGrams(number(micro,"chromium_ug",1e7)/1000000));if(micro.has("selenium_ug"))n.setSelenium(Mass.fromGrams(number(micro,"selenium_ug",1e7)/1000000));}list.add(n.build());break;
    }
   }
   if(list.isEmpty()){emit(a,ticket,true);return;}HealthConnectManager m=a.getSystemService(HealthConnectManager.class);if(m==null)throw new Exception("Health Connect no disponible");m.insertRecords(list,a.getMainExecutor(),new OutcomeReceiver<InsertRecordsResponse,HealthConnectException>(){public void onResult(InsertRecordsResponse r){emit(a,ticket,true);}public void onError(HealthConnectException e){emit(a,ticket,false);}});
  }catch(Exception error){emit(a,ticket,false);}
 }
 static int exerciseType24(JSONObject o){String sport=o.optString("sport","");if(sport.equals("cycling")||o.optBoolean("cycling"))return ExerciseSessionType.EXERCISE_SESSION_TYPE_BIKING;if(sport.equals("running"))return ExerciseSessionType.EXERCISE_SESSION_TYPE_RUNNING;if(sport.equals("walking"))return ExerciseSessionType.EXERCISE_SESSION_TYPE_WALKING;if(sport.equals("swimming")){String mode=o.optString("swimmingMode");if(mode.equals("open_water"))return ExerciseSessionType.EXERCISE_SESSION_TYPE_SWIMMING_OPEN_WATER;if(mode.equals("pool"))return ExerciseSessionType.EXERCISE_SESSION_TYPE_SWIMMING_POOL;return ExerciseSessionType.EXERCISE_SESSION_TYPE_OTHER_WORKOUT;}return ExerciseSessionType.EXERCISE_SESSION_TYPE_STRENGTH_TRAINING;}
 static Class<? extends android.health.connect.datatypes.Record> recordClass(String type)throws Exception{switch(type){case "DISTANCE":return DistanceRecord.class;case "STEPS":return StepsRecord.class;case "EXERCISE":return ExerciseSessionRecord.class;case "SLEEP":return SleepSessionRecord.class;case "WEIGHT":return WeightRecord.class;case "NUTRITION":return NutritionRecord.class;case "HYDRATION":return HydrationRecord.class;default:throw new Exception("Tipo no válido");}}
 static void delete(Main a,String ticket,String json){if(ticket==null||!ticket.matches("[A-Za-z0-9_-]{1,100}"))return;try{JSONArray data=new JSONArray(json);if(data.length()>100)throw new Exception("Lote demasiado grande");for(int i=0;i<data.length();i++){JSONObject o=data.getJSONObject(i);if(!o.getString("id").matches("[A-Za-z0-9_-]{1,100}")||!o.getString("owner").matches("[a-f0-9]{32}")||!o.optString("source").equals("vera")||a.checkSelfPermission("android.permission.health.WRITE_"+o.getString("type"))!=0)throw new Exception("Registro no válido");recordClass(o.getString("type"));}deleteNext(a,ticket,data,0);}catch(Exception e){emit(a,ticket,false);}}
 static void deleteNext(Main a,String ticket,JSONArray data,int index){if(data.length()==0){emit(a,ticket,true);return;}try{ArrayList<RecordIdFilter> ids=new ArrayList<>();for(int i=0;i<data.length();i++){JSONObject o=data.getJSONObject(i);String client="vera23_"+o.getString("owner")+"_"+o.getString("type")+"_"+o.getString("id");ids.add(RecordIdFilter.fromClientRecordId(recordClass(o.getString("type")),client));}HealthConnectManager m=a.getSystemService(HealthConnectManager.class);m.deleteRecords(ids,a.getMainExecutor(),new OutcomeReceiver<Void,HealthConnectException>(){public void onResult(Void r){emit(a,ticket,true);}public void onError(HealthConnectException e){emit(a,ticket,false);}});}catch(Exception e){emit(a,ticket,false);}}
 static void emit(Main a,String ticket,boolean ok){if(a.web!=null&&!a.isFinishing()&&!a.isDestroyed())a.web.evaluateJavascript("window.healthWritten23?.("+JSONObject.quote(ticket)+","+ok+")",null);}
}
